// District lookup map for zero-allocation label retrieval
const DISTRICT_MAP = Object.fromEntries(
  ODISHA_DISTRICTS.map((dist) => [
    dist.id,
    { 'en-IN': dist.nameEn, 'or-IN': dist.nameOr, 'hi-IN': dist.nameHi }
  ])
);

// Backward compatible rawDoctorsData
export const rawDoctorsData = DOCS.map((d) => ({
  id: d[0],
  name: { 'en-IN': d[1], 'or-IN': d[2], 'hi-IN': d[3] },
  nameEn: d[1],
  gender: d[4],
  specialty: d[5],
  specialtyKey: d[6],
  qualifications: d[7],
  regNo: d[8],
  facility: FACS[d[9]],
  facilityEn: FACS[d[9]]['en-IN'],
  location: d[10],
  district: d[11],
  room: ROOMS[d[12]],
  experience: d[13],
  rating: d[14],
  reviewsCount: d[15],
  days: DAYS[d[16]],
  teleAvailable: Boolean(d[17]),
  initials: d[18],
  color: d[19],
  famousFor: FAMS[d[20]],
  hospitalTier: d[21],
  successRate: d[22],
  doctorDegreeLevel: d[23],
  budgetTier: d[24],
  bskyAvailable: Boolean(d[25]),
  opdFee: FEES[d[26]],
  avgWaitTime: WAITS[d[27]],
  avgWaitTimeMinutes: d[28],
  awards: d[29],
  image: getDoctorPhotoUrl({ id: d[0], nameEn: d[1], gender: d[4] })
}));

// Fast caching dictionary for localized lists
const listCache = {};

export const getDoctorsList = (lang = 'or-IN', txt = {}) => {
  const cacheKey = lang;
  if (listCache[cacheKey]) {
    return listCache[cacheKey];
  }

  const result = DOCS.map((d) => {
    const nameObj = { 'en-IN': d[1], 'or-IN': d[2], 'hi-IN': d[3] };
    const facObj = FACS[d[9]];
    const distLabels = DISTRICT_MAP[d[11]] || { 'en-IN': d[11], 'or-IN': d[11], 'hi-IN': d[11] };
    const roomObj = ROOMS[d[12]];
    const daysObj = DAYS[d[16]];
    const famObj = FAMS[d[20]];
    const feeObj = FEES[d[26]];
    const waitObj = WAITS[d[27]];

    const name = nameObj[lang] || d[1];
    const facility = facObj[lang] || facObj['en-IN'];
    const specialty = d[5];
    const specialtyKey = d[6];
    const specialtyLabel = txt[specialtyKey] || specialty;
    const districtLabel = distLabels[lang] || d[11];
    const location = d[10];
    const qualifications = d[7];

    const _search = (name + ' ' + d[1] + ' ' + specialtyLabel + ' ' + specialty + ' ' + facility + ' ' + facObj['en-IN'] + ' ' + location + ' ' + d[11] + ' ' + districtLabel + ' ' + qualifications).toLowerCase();

    return {
      id: d[0],
      name,
      nameEn: d[1],
      gender: d[4],
      specialty,
      specialtyKey,
      specialtyLabel,
      qualifications,
      regNo: d[8],
      facility,
      facilityEn: facObj['en-IN'],
      location,
      district: d[11],
      districtLabel,
      room: roomObj[lang] || roomObj['en-IN'],
      experience: d[13],
      rating: d[14],
      reviewsCount: d[15],
      days: daysObj[lang] || daysObj['en-IN'],
      teleAvailable: Boolean(d[17]),
      initials: d[18],
      color: d[19],
      famousFor: famObj[lang] || famObj['en-IN'],
      hospitalTier: d[21],
      successRate: d[22],
      doctorDegreeLevel: d[23],
      budgetTier: d[24],
      bskyAvailable: Boolean(d[25]),
      opdFee: feeObj[lang] || feeObj['en-IN'],
      avgWaitTime: waitObj[lang] || waitObj['en-IN'],
      avgWaitTimeMinutes: d[28],
      awards: d[29],
      image: getDoctorPhotoUrl({ id: d[0], nameEn: d[1], gender: d[4] }),
      _search
    };
  });

  listCache[cacheKey] = result;
  return result;
};
